def append_once(path, record):
    """Cooperating POSIX writers; no power-failure atomicity guarantee."""
    import fcntl
    import json
    import math
    import os

    def validate(value):
        kind = type(value)
        if value is None or kind in (str, bool, int):
            return
        if kind is float:
            if not math.isfinite(value):
                raise ValueError("Nonfinite JSON number")
            return
        if kind is list:
            for item in value:
                validate(item)
            return
        if kind is dict:
            for key, item in value.items():
                if type(key) is not str:
                    raise ValueError("JSON object keys must be strings")
                validate(item)
            return
        raise ValueError("Not a JSON value")

    def canonical(row):
        if type(row) is not dict:
            raise ValueError("Record must be a JSON object")
        if type(row.get("id")) is not str or not row["id"]:
            raise ValueError("Record needs a nonempty string id")
        validate(row)
        return json.dumps(row, allow_nan=False, ensure_ascii=True,
                          sort_keys=True, separators=(",", ":")).encode("ascii")

    def object_pairs(pairs):
        obj = {}
        for key, value in pairs:
            if key in obj:
                raise ValueError("Duplicate JSON object key")
            obj[key] = value
        return obj

    def bad_constant(value):
        raise ValueError("Nonfinite JSON constant: " + value)

    # Fully serialize before opening or changing the ledger.
    payload = canonical(record)
    candidate_id = json.loads(payload)["id"]
    with open(path, "a+b") as ledger:
        fcntl.flock(ledger.fileno(), fcntl.LOCK_EX)
        try:
            ledger.seek(0)
            seen = {}
            final_line = b""
            for line in ledger:
                final_line = line
                try:
                    row = json.loads(line.decode("utf-8"),
                                     object_pairs_hook=object_pairs,
                                     parse_constant=bad_constant)
                    normalized = canonical(row)
                except (ValueError, TypeError, UnicodeError, RecursionError) as exc:
                    raise ValueError("Malformed ledger row") from exc
                row_id = row["id"]
                if row_id in seen:
                    raise ValueError("Duplicate ledger id")
                seen[row_id] = normalized
            if candidate_id in seen:
                if seen[candidate_id] != payload:
                    raise ValueError("Existing id has different content")
                return False
            separator = b"\n" if final_line and not final_line.endswith(b"\n") else b""
            ledger.seek(0, os.SEEK_END)
            ledger.write(separator + payload + b"\n")
            ledger.flush()
            os.fsync(ledger.fileno())
            return True
        finally:
            fcntl.flock(ledger.fileno(), fcntl.LOCK_UN)
